import{d as t,S as a,i as n,l as o}from"./chunks/framework.CY2TYXqZ.js";const c=JSON.parse(`{"title":"Just a Preview","description":"A white-box engagement against Corvid Labs' internal prompt library, whose editor tells authors that rendering a preview runs in a restricted environment.","frontmatter":{"title":"Just a Preview","number":8,"layout":"challenge","difficulty":"easy","category":"web","backend":"fastapi","app":"app.py","packages":[],"tools":["browser","network","repeater","code"],"source_visible":true,"source_files":["/templates/layout.html","/templates/index.html","/templates/detail.html","/templates/preview.html","/templates/_editor.html","/templates/missing.html","/static/app.css"],"date":"2026-09-06T09:23:32.337Z","tags":["ssti","template-injection","jinja2","fastapi"],"description":"A white-box engagement against Corvid Labs' internal prompt library, whose editor tells authors that rendering a preview runs in a restricted environment.","wasmModule":"/challenge/just-a-preview/runtime.wasm","markdownBody":"\\n# Just a Preview\\n\\n**Client:** Corvid Labs, whose support desk runs its first-line replies through\\na language model.\\n**Engagement:** White-box assessment of the internal prompt library and the\\npage templates shipped alongside it.\\n\\n## Scope\\n\\nIn scope: the Prompt Library served at this origin, every HTTP endpoint it\\nexposes, and the template files mounted into the application image.\\n\\nThe library is reached over the internal network Corvid Labs has opened to you\\nfor this engagement. It carries no sign-in of its own — everyone on the support\\nautomation rota shares it, and anyone who can reach it can draft a template\\nand render a preview of it.\\n\\nOut of scope: the hosting platform, the language model the finished prompts are\\nsent to, other engagements, and denial of service.\\n\\n## Rules of engagement\\n\\nThis is an authorised exercise against a system Corvid Labs controls. Reach the\\nobjective and stop — Corvid Labs is paying for proof of impact, not for damage.\\nStay inside the scope above.\\n\\nCorvid Labs has released the application source and the page templates for this\\nengagement. Read them.\\n\\n## Objective\\n\\nThe template editor tells its authors that rendering a preview happens in a\\nrestricted environment. Corvid Labs put a language model in front of its\\ncustomers on the strength of that sentence, and the platform team would rather\\nhear from you than from a customer whether it holds.\\n\\nDisprove it: make the preview hand back the contents of a file the library was\\nnever meant to read. \`/flag.txt\` sits on the application's filesystem and no\\nroute serves it, so recovering it through the preview is what Corvid Labs will\\naccept as proof of impact. Submit it below to close the engagement.\\n\\n## Deliverable\\n\\nCorvid Labs wants a record of how you got there, not only the result. Log each\\nrequest that moved the assessment forward in the Notes panel, and export the\\nsession when you are done.\\n"},"headers":[],"relativePath":"challenge/just-a-preview/index.md","filePath":"challenge/just-a-preview/index.md"}`),r={name:"challenge/just-a-preview/index.md"};function s(i,e,h,l,p,d){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="just-a-preview" tabindex="-1">Just a Preview <a class="header-anchor" href="#just-a-preview" aria-label="Permalink to “Just a Preview”">​</a></h1><p><strong>Client:</strong> Corvid Labs, whose support desk runs its first-line replies through a language model. <strong>Engagement:</strong> White-box assessment of the internal prompt library and the page templates shipped alongside it.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>In scope: the Prompt Library served at this origin, every HTTP endpoint it exposes, and the template files mounted into the application image.</p><p>The library is reached over the internal network Corvid Labs has opened to you for this engagement. It carries no sign-in of its own — everyone on the support automation rota shares it, and anyone who can reach it can draft a template and render a preview of it.</p><p>Out of scope: the hosting platform, the language model the finished prompts are sent to, other engagements, and denial of service.</p><h2 id="rules-of-engagement" tabindex="-1">Rules of engagement <a class="header-anchor" href="#rules-of-engagement" aria-label="Permalink to “Rules of engagement”">​</a></h2><p>This is an authorised exercise against a system Corvid Labs controls. Reach the objective and stop — Corvid Labs is paying for proof of impact, not for damage. Stay inside the scope above.</p><p>Corvid Labs has released the application source and the page templates for this engagement. Read them.</p><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to “Objective”">​</a></h2><p>The template editor tells its authors that rendering a preview happens in a restricted environment. Corvid Labs put a language model in front of its customers on the strength of that sentence, and the platform team would rather hear from you than from a customer whether it holds.</p><p>Disprove it: make the preview hand back the contents of a file the library was never meant to read. <code>/flag.txt</code> sits on the application&#39;s filesystem and no route serves it, so recovering it through the preview is what Corvid Labs will accept as proof of impact. Submit it below to close the engagement.</p><h2 id="deliverable" tabindex="-1">Deliverable <a class="header-anchor" href="#deliverable" aria-label="Permalink to “Deliverable”">​</a></h2><p>Corvid Labs wants a record of how you got there, not only the result. Log each request that moved the assessment forward in the Notes panel, and export the session when you are done.</p>',14)])])}const g=t(r,[["render",s]]);export{c as __pageData,g as default};
